import{_ as e,a as d,c as r,ac as s}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Redis List（列表） · 1. 定位：解决什么问题至2. 命令速查与示例","description":"有序序列、限长聊天记录与任务队列，包括基本操作、适用场景和使用边界。","frontmatter":{"title":"Redis List（列表） · 1. 定位：解决什么问题至2. 命令速查与示例","description":"有序序列、限长聊天记录与任务队列，包括基本操作、适用场景和使用边界。","splitFrom":"middleware/redis/plus/subjects/list.md","showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"Redis List（列表）","summary":"有序序列、限长聊天记录与任务队列，包括基本操作、适用场景和使用边界。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":{"text":"Redis List（列表）","link":"/middleware/redis/plus/subjects/list"},"next":{"text":"Redis List（列表） · 3. 底层编码与内存至8. Go 客户端与最佳实践","link":"/middleware/redis/plus/subjects/list-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Redis List（列表）","link":"/middleware/redis/plus/subjects/list"},"next":{"text":"Redis List（列表） · 3. 底层编码与内存至8. Go 客户端与最佳实践","link":"/middleware/redis/plus/subjects/list-part-02"}},"headers":[],"relativePath":"middleware/redis/plus/subjects/list-part-01.md","filePath":"middleware/redis/plus/subjects/list-part-01.md"}'),a={name:"middleware/redis/plus/subjects/list-part-01.md"};function l(i,t,n,o,p,c){return d(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="redis-list-列表-·-1-定位-解决什么问题至2-命令速查与示例" tabindex="-1">Redis List（列表） · 1. 定位：解决什么问题至2. 命令速查与示例 <a class="header-anchor" href="#redis-list-列表-·-1-定位-解决什么问题至2-命令速查与示例" aria-label="Permalink to &quot;Redis List（列表） · 1. 定位：解决什么问题至2. 命令速查与示例&quot;">​</a></h1><p><a href="/middleware/redis/plus/subjects/list">返回分篇目录</a></p><p>本文按 Redis 8.2.10 核对编码与配置默认值；命令的引入版本另行标注。生产配置可能不同，可通过 CONFIG GET 查询。示例面向独立实验服务，运行结果和内存数字未在本次实测。</p><h2 id="list" tabindex="-1">Redis List（列表） <a class="header-anchor" href="#list" aria-label="Permalink to &quot;Redis List（列表） {#list}&quot;">​</a></h2><p>本文按 Redis 8.2.10 核对编码与配置默认值；命令的引入版本另行标注。生产配置可能不同，可通过 CONFIG GET 查询。示例面向独立实验服务，运行结果和内存数字未在本次实测。</p><h2 id="position" tabindex="-1">1. 定位：解决什么问题 <a class="header-anchor" href="#position" aria-label="Permalink to &quot;1. 定位：解决什么问题 {#position}&quot;">​</a></h2><p>List 是允许重复、保留顺序的字符串序列。适合最近聊天记录和两端队列；按分数排序用 ZSet，去重用 Set，需要事件游标、消费组与待确认记录时比较 Stream。</p><h3 id="基本操作示例" tabindex="-1">基本操作示例 <a class="header-anchor" href="#基本操作示例" aria-label="Permalink to &quot;基本操作示例 {#基本操作示例}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RPUSH learn:types:queue task-a task-b task-a</span></span>
<span class="line"><span>LPOP learn:types:queue</span></span>
<span class="line"><span>LRANGE learn:types:queue 0 1</span></span></code></pre></div><p>预期弹出 <code>task-a</code>，剩余前两个元素为 <code>task-b</code>、<code>task-a</code>。弹出会移除元素，不能只靠这个流程就保证任务不会丢失；消费者取出后崩溃时，需要额外的确认和重试设计。避免把 List 当成任意位置都能常数时间访问的数组。</p><p>参考：<a href="https://redis.io/docs/latest/develop/data-types/lists/" target="_blank" rel="noopener noreferrer">List</a>。</p><h3 id="限长聊天记录" tabindex="-1">限长聊天记录 <a class="header-anchor" href="#限长聊天记录" aria-label="Permalink to &quot;限长聊天记录 {#限长聊天记录}&quot;">​</a></h3><p><code>LPUSH chat:room1 message</code> 将新消息放在左侧，<code>LTRIM chat:room1 0 199</code> 保留最近 200 条。若要求每次写入后立刻满足长度上限，可用事务或 Lua 把两步合起来。</p><p>List 保存历史，Pub/Sub 负责在线推送，二者不能混为一谈。需要离线重放和消费进度时，可阅读 <a href="/middleware/redis/plus/subjects/stream">Stream</a>。</p><h2 id="commands" tabindex="-1">2. 命令速查与示例 <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;2. 命令速查与示例 {#commands}&quot;">​</a></h2><p>按用途分组，共 <strong>22 项</strong>，覆盖 Redis 8.2.10 的本类型命令及子命令。点击命令名查看官方参数。示例在 redis-cli 中逐行输入，<strong>每次换例子前重置下面的教学数据</strong>。</p><details class="details custom-block"><summary>准备与重置示例数据</summary><p>在独立实验实例的 <strong>redis-cli 交互模式</strong>逐行输入，避免 shell 对引号、<code>&gt;</code>、<code>*</code>、括号等符号进行解释。<strong>每个例子独立使用；换例子前重新执行下面的准备段</strong>，否则删除、弹出、过期和修改操作会影响后续结果。准备段仅重置列出的教学键，确认这些键不承载业务数据。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UNLINK learn:{list}:a learn:{list}:b</span></span>
<span class="line"><span>RPUSH learn:{list}:a a b c</span></span>
<span class="line"><span>RPUSH learn:{list}:b x y</span></span></code></pre></div><p>示例的返回说明以刚完成准备段为前提，随机结果与剩余 TTL 不固定。带同一 <code>{...}</code> 的教学键便于在 Cluster 中满足相关多键操作的同槽要求。</p></details><h3 id="两端写入与弹出" tabindex="-1">两端写入与弹出 <a class="header-anchor" href="#两端写入与弹出" aria-label="Permalink to &quot;两端写入与弹出 {#两端写入与弹出}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-lpush"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/lpush.json" target="_blank" rel="noopener noreferrer">LPUSH</a><br>从左侧插入</td><td><code>LPUSH learn:{list}:a x y</code><br>依次向左插入，前两项为 y、x；返回新长度 5。</td><td>O(K)</td></tr><tr><td><span id="cmd-rpush"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/rpush.json" target="_blank" rel="noopener noreferrer">RPUSH</a><br>从右侧插入</td><td><code>RPUSH learn:{list}:a d</code><br>右侧增加 d，返回 4。</td><td>O(K)</td></tr><tr><td><span id="cmd-lpushx"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/lpushx.json" target="_blank" rel="noopener noreferrer">LPUSHX</a><br>仅已有列表左侧插入</td><td><code>LPUSHX learn:{list}:a x</code><br>键存在，返回新长度 4。</td><td>O(K)</td></tr><tr><td><span id="cmd-rpushx"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/rpushx.json" target="_blank" rel="noopener noreferrer">RPUSHX</a><br>仅已有列表右侧插入</td><td><code>RPUSHX learn:{list}:a d</code><br>键存在，返回新长度 4。</td><td>O(K)</td></tr><tr><td><span id="cmd-lpop"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/lpop.json" target="_blank" rel="noopener noreferrer">LPOP</a><br>左侧弹出</td><td><code>LPOP learn:{list}:a 2</code><br>返回并移除 a、b；COUNT 从 6.2 起支持。</td><td>O(M)</td></tr><tr><td><span id="cmd-rpop"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/rpop.json" target="_blank" rel="noopener noreferrer">RPOP</a><br>右侧弹出</td><td><code>RPOP learn:{list}:a</code><br>返回并移除 c。</td><td>O(M)</td></tr><tr><td><span id="cmd-lmpop"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/lmpop.json" target="_blank" rel="noopener noreferrer">LMPOP</a><br>从多个列表弹出</td><td><code>LMPOP 2 learn:{list}:a learn:{list}:b LEFT COUNT 2</code><br>从首个非空列表 a 返回 a、b。</td><td>O(K+M)</td></tr></tbody></table><h3 id="阻塞与跨列表移动" tabindex="-1">阻塞与跨列表移动 <a class="header-anchor" href="#阻塞与跨列表移动" aria-label="Permalink to &quot;阻塞与跨列表移动 {#阻塞与跨列表移动}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-blpop"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/blpop.json" target="_blank" rel="noopener noreferrer">BLPOP</a><br>等待左侧弹出</td><td><code>BLPOP learn:{list}:a learn:{list}:b 1</code><br>准备数据非空时立即返回键名和 a；等待上限 1 秒。</td><td>O(K)</td></tr><tr><td><span id="cmd-brpop"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/brpop.json" target="_blank" rel="noopener noreferrer">BRPOP</a><br>等待右侧弹出</td><td><code>BRPOP learn:{list}:a 1</code><br>返回键名和 c。</td><td>O(K)</td></tr><tr><td><span id="cmd-blmpop"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/blmpop.json" target="_blank" rel="noopener noreferrer">BLMPOP</a><br>等待多列表批量弹出</td><td><code>BLMPOP 1 2 learn:{list}:a learn:{list}:b LEFT COUNT 2</code><br>最多等待 1 秒，从首个非空列表弹出两项。</td><td>O(K+M)</td></tr><tr><td><span id="cmd-lmove"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/lmove.json" target="_blank" rel="noopener noreferrer">LMOVE</a><br>在两列表间原子移动</td><td><code>LMOVE learn:{list}:a learn:{list}:b RIGHT LEFT</code><br>返回 c，并将其移到 b 列表左侧。</td><td>O(1)</td></tr><tr><td><span id="cmd-blmove"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/blmove.json" target="_blank" rel="noopener noreferrer">BLMOVE</a><br>等待原子移动</td><td><code>BLMOVE learn:{list}:a learn:{list}:b RIGHT LEFT 1</code><br>非空时立即移动 c；最多等待 1 秒。</td><td>O(1)</td></tr></tbody></table><h3 id="查询与列表修改" tabindex="-1">查询与列表修改 <a class="header-anchor" href="#查询与列表修改" aria-label="Permalink to &quot;查询与列表修改 {#查询与列表修改}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-llen"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/llen.json" target="_blank" rel="noopener noreferrer">LLEN</a><br>列表长度</td><td><code>LLEN learn:{list}:a</code><br>返回 3。</td><td>O(1)</td></tr><tr><td><span id="cmd-lindex"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/lindex.json" target="_blank" rel="noopener noreferrer">LINDEX</a><br>读取指定下标</td><td><code>LINDEX learn:{list}:a 1</code><br>返回 b，负下标从尾部计数。</td><td>最坏 O(N)</td></tr><tr><td><span id="cmd-lrange"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/lrange.json" target="_blank" rel="noopener noreferrer">LRANGE</a><br>读取区间</td><td><code>LRANGE learn:{list}:a 0 1</code><br>返回 a、b，停止下标包含在内。</td><td>O(S+M)</td></tr><tr><td><span id="cmd-lpos"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/lpos.json" target="_blank" rel="noopener noreferrer">LPOS</a><br>查找元素下标</td><td><code>LPOS learn:{list}:a b</code><br>返回 1；可用 RANK/COUNT/MAXLEN 限定查找。</td><td>平均 O(N)</td></tr><tr><td><span id="cmd-lset"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/lset.json" target="_blank" rel="noopener noreferrer">LSET</a><br>替换指定下标</td><td><code>LSET learn:{list}:a 1 B</code><br>返回 OK，中间元素变成 B。</td><td>最坏 O(N)</td></tr><tr><td><span id="cmd-linsert"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/linsert.json" target="_blank" rel="noopener noreferrer">LINSERT</a><br>在指定值前后插入</td><td><code>LINSERT learn:{list}:a BEFORE b x</code><br>插入后长度为 4。</td><td>O(S)</td></tr><tr><td><span id="cmd-lrem"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/lrem.json" target="_blank" rel="noopener noreferrer">LREM</a><br>按值移除</td><td><code>LREM learn:{list}:a 1 b</code><br>从左向右最多移除一个 b，返回 1。</td><td>O(N+M)</td></tr><tr><td><span id="cmd-ltrim"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/ltrim.json" target="_blank" rel="noopener noreferrer">LTRIM</a><br>只保留指定区间</td><td><code>LTRIM learn:{list}:a 0 1</code><br>返回 OK，仅保留 a、b。</td><td>O(R)</td></tr></tbody></table><h3 id="旧版兼容命令" tabindex="-1">旧版兼容命令 <a class="header-anchor" href="#旧版兼容命令" aria-label="Permalink to &quot;旧版兼容命令 {#旧版兼容命令}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-rpoplpush"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/rpoplpush.json" target="_blank" rel="noopener noreferrer">RPOPLPUSH</a><br>旧式右出左入</td><td><code>RPOPLPUSH learn:{list}:a learn:{list}:b</code><br>返回 c；新代码用 LMOVE ... RIGHT LEFT。</td><td>O(1)</td></tr><tr><td><span id="cmd-brpoplpush"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/brpoplpush.json" target="_blank" rel="noopener noreferrer">BRPOPLPUSH</a><br>旧式阻塞右出左入</td><td><code>BRPOPLPUSH learn:{list}:a learn:{list}:b 1</code><br>返回 c；新代码用 BLMOVE。</td><td>O(1)</td></tr></tbody></table><details class="details custom-block"><summary>版本与复杂度补充</summary><p>下表保留每条命令的引入版本、兼容状态及复杂度符号含义；复杂度不包含全部网络传输、内存分配和等待成本。</p><table tabindex="0"><thead><tr><th>命令</th><th>引入版本与状态</th><th>复杂度说明</th></tr></thead><tbody><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-lpush">LPUSH</a></td><td>1.0.0</td><td>O(K)，K 为本次指定元素数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-rpush">RPUSH</a></td><td>1.0.0</td><td>O(K)，K 为本次指定元素数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-lpushx">LPUSHX</a></td><td>2.2.0</td><td>O(K)，K 为本次指定元素数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-rpushx">RPUSHX</a></td><td>2.2.0</td><td>O(K)，K 为本次指定元素数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-lpop">LPOP</a></td><td>1.0.0</td><td>O(M)，M 为返回元素数；单元素 O(1)。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-rpop">RPOP</a></td><td>1.0.0</td><td>O(M)，M 为返回元素数；单元素 O(1)。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-lmpop">LMPOP</a></td><td>7.0.0</td><td>O(K+M)，K 为提供的键数，M 为返回元素数；阻塞等待时间另计。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-blpop">BLPOP</a></td><td>2.0.0</td><td>O(K)，K 为提供的键数；阻塞等待时间另计。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-brpop">BRPOP</a></td><td>2.0.0</td><td>O(K)，K 为提供的键数；阻塞等待时间另计。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-blmpop">BLMPOP</a></td><td>7.0.0</td><td>O(K+M)，K 为提供的键数，M 为返回元素数；阻塞等待时间另计。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-lmove">LMOVE</a></td><td>6.2.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-blmove">BLMOVE</a></td><td>6.2.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-llen">LLEN</a></td><td>1.0.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-lindex">LINDEX</a></td><td>1.0.0</td><td>最坏 O(N)，N 为列表长度；首尾访问或替换可为 O(1)。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-lrange">LRANGE</a></td><td>1.0.0</td><td>O(S+M)，S 为定位起点的遍历距离，M 为返回元素数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-lpos">LPOS</a></td><td>6.0.6</td><td>平均 O(N)，N 为列表长度；靠近两端匹配或指定 MAXLEN 可减少扫描量。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-lset">LSET</a></td><td>1.0.0</td><td>最坏 O(N)，N 为列表长度；首尾访问或替换可为 O(1)。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-linsert">LINSERT</a></td><td>2.2.0</td><td>O(S)，S 为找到 pivot 前扫描的元素数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-lrem">LREM</a></td><td>1.0.0</td><td>O(N+M)，N 为列表长度，M 为删除数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-ltrim">LTRIM</a></td><td>1.0.0</td><td>O(R)，R 为实际移除元素数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-rpoplpush">RPOPLPUSH</a></td><td>1.2.0；从 6.2.0 起弃用（兼容保留）</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/list-part-01#cmd-brpoplpush">BRPOPLPUSH</a></td><td>2.2.0；从 6.2.0 起弃用（兼容保留）</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr></tbody></table></details><p>通用键操作见<a href="/middleware/redis/base/basic/keys">键与过期时间</a>，这里集中列出类型自身的命令。</p>`,27)])])}const m=e(a,[["render",l]]);export{h as __pageData,m as default};
